def config_value(text: str, key: str) -> str:
    """Return the value for ``key`` in ``name=value`` config text.

    Each line holds one ``name=value`` pair. Surrounding whitespace on the
    name and value is ignored. Blank lines and lines starting with ``#``
    are skipped. The split happens on the first ``=``, so a value may
    contain ``=``. Returns an empty string when the key is absent.
    The function does not read files; it works only on ``text``.
    """
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        name, sep, value = line.partition("=")
        if sep and name.strip() == key:
            return value.strip()
    return ""


def test_config_value_basic() -> None:
    assert config_value("host=localhost\nport=8080", "port") == "8080"


def test_config_value_missing_key_returns_empty() -> None:
    assert config_value("host=localhost", "port") == ""


def test_config_value_empty_text_returns_empty() -> None:
    assert config_value("", "host") == ""


def test_config_value_strips_whitespace() -> None:
    assert config_value("  host  =  localhost  \n", "host") == "localhost"


def test_config_value_skips_comments_and_blank_lines() -> None:
    text = "# server settings\n\nhost=localhost\n# port=1\n"
    assert config_value(text, "host") == "localhost"
    assert config_value(text, "port") == ""


def test_config_value_splits_on_first_equals() -> None:
    assert config_value("expr=a=b=c", "expr") == "a=b=c"


def test_config_value_key_match_is_exact() -> None:
    assert config_value("hostname=example", "host") == ""
